/* STM32CubeU5 HAL SPI transmission by GPDMA.
 *
 * Unmodified HAL. SPI1 is master, full duplex, software NSS, 8-bit frames; GPDMA1 channel 0
 * serves the SPI1_TX request, memory to peripheral, as generated by STM32CubeMX. The robot test
 * attaches a slave that logs every received byte. Checks: HAL_SPI_Transmit_DMA of 8 bytes ends
 * with HAL_SPI_TxCpltCallback and no error callback. */

#include "clock_160mhz.h"

SPI_HandleTypeDef hspi1;
DMA_HandleTypeDef hdmaTx;

volatile uint32_t step;
volatile uint32_t failedStep;
volatile uint32_t transferComplete;
volatile uint32_t transferError;

static uint8_t txData[8] = {0xA1u, 0xB2u, 0xC3u, 0xD4u, 0xE5u, 0xF6u, 0x07u, 0x18u};

void SysTick_Handler(void)
{
    HAL_IncTick();
}

void GPDMA1_Channel0_IRQHandler(void)
{
    HAL_DMA_IRQHandler(&hdmaTx);
}

void SPI1_IRQHandler(void)
{
    HAL_SPI_IRQHandler(&hspi1);
}

void HAL_SPI_TxCpltCallback(SPI_HandleTypeDef *hspi)
{
    if (hspi == &hspi1)
    {
        transferComplete = 1u;
    }
}

void HAL_SPI_ErrorCallback(SPI_HandleTypeDef *hspi)
{
    if (hspi == &hspi1)
    {
        transferError = 1u;
    }
}

static void check(HAL_StatusTypeDef status, uint32_t at)
{
    step = at;
    if (status != HAL_OK)
    {
        failedStep = at;
        for (;;)
        {
        }
    }
}

void HAL_SPI_MspInit(SPI_HandleTypeDef *hspi)
{
    if (hspi->Instance != SPI1)
    {
        return;
    }
    __HAL_RCC_SPI1_CLK_ENABLE();
    __HAL_RCC_GPDMA1_CLK_ENABLE();

    hdmaTx.Instance = GPDMA1_Channel0;
    hdmaTx.Init.Request = GPDMA1_REQUEST_SPI1_TX;
    hdmaTx.Init.BlkHWRequest = DMA_BREQ_SINGLE_BURST;
    hdmaTx.Init.Direction = DMA_MEMORY_TO_PERIPH;
    hdmaTx.Init.SrcInc = DMA_SINC_INCREMENTED;
    hdmaTx.Init.DestInc = DMA_DINC_FIXED;
    hdmaTx.Init.SrcDataWidth = DMA_SRC_DATAWIDTH_BYTE;
    hdmaTx.Init.DestDataWidth = DMA_DEST_DATAWIDTH_BYTE;
    hdmaTx.Init.Priority = DMA_LOW_PRIORITY_HIGH_WEIGHT;
    hdmaTx.Init.SrcBurstLength = 1;
    hdmaTx.Init.DestBurstLength = 1;
    hdmaTx.Init.TransferAllocatedPort = DMA_SRC_ALLOCATED_PORT0 | DMA_DEST_ALLOCATED_PORT1;
    hdmaTx.Init.TransferEventMode = DMA_TCEM_BLOCK_TRANSFER;
    hdmaTx.Init.Mode = DMA_NORMAL;
    if (HAL_DMA_Init(&hdmaTx) != HAL_OK)
    {
        failedStep = 100;
        for (;;)
        {
        }
    }
    __HAL_LINKDMA(hspi, hdmatx, hdmaTx);

    HAL_NVIC_SetPriority(GPDMA1_Channel0_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(GPDMA1_Channel0_IRQn);
    HAL_NVIC_SetPriority(SPI1_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(SPI1_IRQn);
}

int main(void)
{
    check(HAL_Init(), 1);
    check(SystemClockConfig160MHz(), 2);

    hspi1.Instance = SPI1;
    hspi1.Init.Mode = SPI_MODE_MASTER;
    hspi1.Init.Direction = SPI_DIRECTION_2LINES;
    hspi1.Init.DataSize = SPI_DATASIZE_8BIT;
    hspi1.Init.CLKPolarity = SPI_POLARITY_LOW;
    hspi1.Init.CLKPhase = SPI_PHASE_1EDGE;
    hspi1.Init.NSS = SPI_NSS_SOFT;
    hspi1.Init.BaudRatePrescaler = SPI_BAUDRATEPRESCALER_16;
    hspi1.Init.FirstBit = SPI_FIRSTBIT_MSB;
    hspi1.Init.TIMode = SPI_TIMODE_DISABLE;
    hspi1.Init.CRCCalculation = SPI_CRCCALCULATION_DISABLE;
    hspi1.Init.CRCPolynomial = 0x7;
    hspi1.Init.NSSPMode = SPI_NSS_PULSE_DISABLE;
    hspi1.Init.NSSPolarity = SPI_NSS_POLARITY_LOW;
    hspi1.Init.FifoThreshold = SPI_FIFO_THRESHOLD_01DATA;
    hspi1.Init.MasterSSIdleness = SPI_MASTER_SS_IDLENESS_00CYCLE;
    hspi1.Init.MasterInterDataIdleness = SPI_MASTER_INTERDATA_IDLENESS_00CYCLE;
    hspi1.Init.MasterReceiverAutoSusp = SPI_MASTER_RX_AUTOSUSP_DISABLE;
    hspi1.Init.MasterKeepIOState = SPI_MASTER_KEEP_IO_STATE_DISABLE;
    hspi1.Init.IOSwap = SPI_IO_SWAP_DISABLE;
    hspi1.Init.ReadyMasterManagement = SPI_RDY_MASTER_MANAGEMENT_INTERNALLY;
    hspi1.Init.ReadyPolarity = SPI_RDY_POLARITY_HIGH;
    check(HAL_SPI_Init(&hspi1), 3);

    check(HAL_SPI_Transmit_DMA(&hspi1, txData, sizeof(txData)), 4);
    const uint32_t start = HAL_GetTick();
    while (!transferComplete && !transferError)
    {
        if (HAL_GetTick() - start > 100u)
        {
            failedStep = 5;
            for (;;)
            {
            }
        }
    }

    step = 6;
    for (;;)
    {
    }
}
